-- tests/test_recipe_reagents.lua — the recipe-reagent table Item Search reads (IS-DW-02,
-- DropWatcher#17): core/RecipeReagentsForever.lua, generated by tools/seeds/recipes.py. That the
-- file equals the generator's output is tools/seeds/test_recipes.py's gate; these cases pin how
-- the shipped file loads and builds on each client (clients-§4, clients-§6).

local T = _G.DW_TEST
local test, assertEqual, assertTrue, assertNil = T.test, T.assertEqual, T.assertTrue, T.assertNil

local FOREVER_ONLY = (not T.forever) and "WoW Forever's alone (clients-§4): the Retail case below asserts it is inert" or nil
local RETAIL_ONLY = T.forever and "the Retail profile's inert case; the Forever cases above cover WoW Forever" or nil

test("recipe reagents: on WoW Forever the table is built on the first ask, once, with its build", function()
    local RR = T.newAddon().RecipeReagents
    local data = RR.Get()
    assertTrue(type(data) == "table", "built on the first ask")
    assertTrue(type(data.build) == "string" and data.build:match("^%d+%.%d+%.%d+%.%d+$") ~= nil, tostring(data.build))
    -- red under: a second ask that builds the rows again
    assertTrue(RR.Get() == data, "the same table on every later ask")
end, FOREVER_ONLY)

test("recipe reagents: every recipe has its ranks and reagents, and byReagent indexes each one exactly", function()
    local data = T.newAddon().RecipeReagents.Get()
    local recipes, indexed = 0, 0
    for spell, r in pairs(data.recipes) do
        recipes = recipes + 1
        assertTrue(type(r.skillLine) == "number" and type(r.min) == "number", "spell " .. spell)
        assertTrue(type(r.yellow) == "number" and type(r.gray) == "number" and r.yellow <= r.gray, "spell " .. spell)
        local n = 0
        for item, count in pairs(r.reagents) do
            n = n + 1
            assertTrue(type(item) == "number" and type(count) == "number" and count > 0, "spell " .. spell)
            local found = false
            for _, s in ipairs(data.byReagent[item] or {}) do found = found or s == spell end
            -- red under: a reagent the index does not lead back to its recipe from
            assertTrue(found, ("item %d does not list spell %d"):format(item, spell))
        end
        assertTrue(n > 0, "a recipe without reagents is left out by the generator: spell " .. spell)
    end
    for item, spells in pairs(data.byReagent) do
        for _, spell in ipairs(spells) do
            indexed = indexed + 1
            -- red under: an index row naming a recipe that does not take the item
            assertTrue(data.recipes[spell] and data.recipes[spell].reagents[item] ~= nil, ("%d -> %d"):format(item, spell))
        end
    end
    assertTrue(recipes > 1000, "the whole table, not a stub: " .. recipes)
    assertTrue(indexed >= recipes)
end, FOREVER_ONLY)

test("recipe reagents: a recipe two professions teach lists both lines; the rest list none", function()
    local data = T.newAddon().RecipeReagents.Get()
    local shared = 0
    for _, r in pairs(data.recipes) do
        if r.skillLines then
            shared = shared + 1
            assertTrue(#r.skillLines > 1); assertEqual(r.skillLines[1], r.skillLine)
        end
    end
    assertTrue(shared < 10, "only the few shared recipes carry skillLines: " .. shared)
end, FOREVER_ONLY)

test("recipe reagents: a recipe's teaching item is a number; taughtBy, when set, lists it first with the others", function()
    local data = T.newAddon().RecipeReagents.Get()
    local taught, trainer, more = 0, 0, 0
    for spell, r in pairs(data.recipes) do
        if r.taught == nil then
            trainer = trainer + 1
            assertNil(r.taughtBy, "a trainer's recipe has no teaching item: spell " .. spell)
        else
            taught = taught + 1
            assertTrue(type(r.taught) == "number" and r.taught > 0, "spell " .. spell)
            if r.taughtBy then
                more = more + 1
                -- red under: a taughtBy list that does not start with the row's own (lowest) item
                assertTrue(#r.taughtBy > 1 and r.taughtBy[1] == r.taught, "spell " .. spell)
            end
        end
    end
    -- Roast Raptor (15855), a Raptor Flesh recipe of the owner's screenshot, is taught by its recipe item.
    assertEqual(data.recipes[15855].taught, 12228)
    assertTrue(taught > trainer and trainer > 0 and more > 0 and more < 100, ("%d %d %d"):format(taught, trainer, more))
end, FOREVER_ONLY)

test("recipe reagents: the gathering lines' recipes are in the table with their breakpoints (round 4)", function()
    local data = T.newAddon().RecipeReagents.Get()
    -- red under: the table holding the crafting lines alone (Incense Candle learned-only, Skill "–")
    local candle = data.recipes[1229705]
    assertTrue(candle ~= nil, "Incense Candle, a Herbalism recipe")
    assertEqual(candle.skillLine, 182); assertEqual(candle.made, 279962)
    assertEqual(candle.yellow, 20); assertEqual(candle.gray, 20)
    assertEqual(candle.reagents[2447], 1, "Peacebloom")
    assertEqual(data.recipes[2657].skillLine, 186, "Smelt Copper, Mining")
    assertEqual(data.recipes[1229745].skillLine, 356, "Fish Bowl, Fishing")
    assertEqual(data.recipes[1229517].skillLine, 393, "Camp Chair, Skinning")
    local found = false
    for _, s in ipairs(data.byReagent[2447]) do found = found or s == 1229705 end
    assertTrue(found, "Peacebloom leads to Incense Candle")
end, FOREVER_ONLY)

-- ── Retail: inert ───────────────────────────────────────────────────────────────────────────

test("recipe reagents: on Retail nothing is built and the table answers nil", function()
    local NS = T.newAddon()
    assertTrue(NS.RecipeReagents ~= nil, "the module is there on both clients")
    -- red under: a Retail load that builds (or answers) WoW Forever's rows
    assertNil(NS.RecipeReagents.Get()); assertNil(NS.RecipeReagents.Get())
end, RETAIL_ONLY)
